MagickBooleanType SkipDXTnMipmaps(Image* image, DDSInfo* dds_info, int texel_size, ExceptionInfo* exception) {
    if ((image->blob != (void *) NULL) && (image->blob->length <= 0))
        return MagickFalse;

    if ((dds_info->mipmaps == 0) || ((dds_info->texture_type != TextureTypeTexture) && (dds_info->texture_type != TextureTypeCubeMap)))
        return MagickTrue;

    for (int level = 1; level < dds_info->mipmaps; level++) {
        size_t width = dds_info->width / (1 << level);
        size_t height = dds_info->height / (1 << level);

        if (width == 0 || height == 0)
            return MagickFalse;

        size_t mipmap_size = ((width + 3) / 4) * ((height + 3) / 4) * ((dds_info->bps * dds_info->components) / 8);

        if (SeekBlob(image, (MagickSizeType)mipmap_size, SEEK_CUR) == MagickFalse)
            return MagickFalse;
    }

    return MagickTrue;
}

MagickBooleanType SkipDXTnMipmaps(Image* image, DDSInfo* dds_info, int texel_size, ExceptionInfo* exception) {
  ssize_t
    offset = 0;

  size_t
    level = 0;

  MagickBooleanType
    status = MagickTrue;

  if (dds_info->mipmap_levels > 1) {
    MagickSizeType
      width = dds_info->width,
      height = dds_info->height;

    while (level < dds_info->mipmap_levels - 1) {
      MagickSizeType
        dxtn_width,
        dxtb_width,
        dxt_height;

      dxtb_width = MagickMax(1, (width + 3) >> 2);
      dxtb_width *= 4;
      dxtn_width = MagickMax(1, (width + 3) >> 2);
      dxt_height = MagickMax(1, (height + 3) >> 2);

      if ((dxtb_width * dxt_height * (size_t) texel_size) == 0)
      {
        (void) ThrowMagickException(exception, GetMagickModule(), ImageError, "InvalidImage", "'");
        return MagickFalse;
      }

      offset += (ssize_t) (dxtb_width * dxt_height * (size_t) texel_size);

      if ((size_t) (image->blob != (void**) NULL && image->blob != NULL && image->blob->length) < (size_t) (offset)) {
        (void) ThrowMagickException(exception, GetMagickModule(), ImageError, "UnexpectedEndOfFile", "'");
        return MagickFalse;
      }

      width >>= 1;
      height >>= 1;
      level++;
    }

    if (SeekBlob(image, offset, SEEK_CUR) != 0)
      return MagickFalse;
  }

  return status;
}

MagickBooleanType SkipDXTnMipmaps(Image *image, DDSInfo *dds_info, int texel_size, ExceptionInfo *exception) {
  if ((image->blob == (void *) NULL) || (image->blob->length == 0))
    return MagickFalse;

  size_t offset = 0;
  size_t width = dds_info->width;
  size_t height = dds_info->height;

  if (dds_info->mipmaps > 0 && (dds_info->texture || dds_info->cube_map)) {
    for (int level = 0; level < dds_info->mipmaps; ++level) {
      size_t width_level = width > 1 ? width / 2 : 1;
      size_t height_level = height > 1 ? height / 2 : 1;
      size_t block_width = MagickMax(1, width_level / 4);
      size_t block_height = MagickMax(1, height_level / 4);
      size_t block_count = block_width * block_height;
      size_t size_level = block_count * texel_size;

      offset += size_level;

      width = width_level;
      height = height_level;

      if (offset > image->blob->length) {
        (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
                                    "UnexpectedEndOfFile", "`%s'", image->filename);
        return MagickFalse;
      }
    }

    if (SeekBlob(image, offset, 0) != offset) {
      (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
                                  "UnableToSeekToMipmap", "`%s'", image->filename);
      return MagickFalse;
    }
  }

  return MagickTrue;
}

MagickBooleanType SkipDXTnMipmaps(Image *image, DDSInfo *dds_info, int texel_size, ExceptionInfo *exception) {
  if ((image->blob == (void *) NULL) || (image->blob->length == 0)) {
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
      "PrematureEndOfBlob", "  ");
    return(MagickFalse);
  }

  if ((dds_info->flags & DDSPCMIPMAP) &&
      ((dds_info->type == Texture) || (dds_info->type == CubeMap))) {
    size_t
      offset;

    offset = dds_info->data_offset;
    while (offset < image->blob->length) {
      register ssize_t
        x;

      for (x = 0; x < (ssize_t) (image->columns + 7) >> 3; x++) {
        if (offset >= image->blob->length)
          break;
        offset += texel_size;
      }

      if (x != (ssize_t) ((image->columns + 7) >> 3))
        break;

      for (x = 0; x < (ssize_t) (image->rows + 3) >> 2; x++) {
        if (offset >= image->blob->length)
          break;
        offset += (image->columns + 7) >> 3;
        offset *= texel_size;
      }

      if (x != (ssize_t) ((image->rows + 3) >> 2))
        break;
    }

    if (offset >= image->blob->length) {
      (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
        "PrematureEndOfBlob", "  ");
      return(MagickFalse);
    }

    image->blob->offset = offset;
    image->blob->length -= offset;
    image->scene = 0;
    image->columns >>= 1;
    image->rows >>= 1;
  }

  return(MagickTrue);
}

MagickBooleanType SkipDXTnMipmaps(Image* image, DDSInfo* dds_info, int texel_size, ExceptionInfo* exception) {
  if ((dds_info->mipmaps > 0) && ((dds_info->flags & DDS_TEXTURE) || (dds_info->flags & DDS_CUBEMAP))) {
    size_t offset = dds_info->data_offset;
    size_t width = dds_info->width;
    size_t height = dds_info->height;

    for (size_t level = 0; level < dds_info->mipmaps; level++) {
      size_t row_size = ((width + 3) / 4) * ((height + 3) / 4) * texel_size;

      if (offset + row_size > image->blob->length) {
        (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
                                    "UnableToReadImageData", "`%s'", image->filename);
        return MagickFalse;
      }

      offset += row_size;

      width = Max(width >> 1, 1);
      height = Max(height >> 1, 1);
    }

    image->blob->offset = offset;
    return MagickFalse;
  }

  return MagickTrue;
}
